interface LinearIssueUpdateInput {
  /** Assignee user UUID or 'me' */
  assignee?: string;
  /** Clear the parent issue (cannot combine with parent) @default null */
  clearParent?: boolean;
  /** New description */
  description?: string;
  /** Issue id or identifier (e.g. GUZ-85) */
  id: string;
  /** Parent issue id or identifier */
  parent?: string;
  /** Workflow state name or UUID (names resolve from the issue identifier team, or team) */
  state?: string;
  /** Team id, key, or name for state lookup */
  team?: string;
  /** New title */
  title?: string;
}

interface LinearIssueUpdateOutput {
  blocked_by?: string[];
  description?: string | null;
  id: string;
  identifier: string;
  parent?: string | null;
  state: string;
  title: string;
  url: string;
}

/** Update a Linear issue by id or identifier. Needs at least one of title, description, state, assignee, parent, clearParent. Returns the updated issue. Requires LINEAR_API_KEY environment variable. */
declare function linear_issue_update(input: LinearIssueUpdateInput): Promise<LinearIssueUpdateOutput>;

interface JiraUpdateInput {
  assignee?: string;
  boardId?: number;
  description?: string;
  issueType?: string;
  priority?: string;
  sprint?: string;
  status?: string;
  ticketKey: string;
}

interface JiraUpdateFieldUpdateResult {
  error?: string | null;
  field: string;
  success: boolean;
  value?: string | null;
}

interface JiraUpdateOutput {
  fields_updated: JiraUpdateFieldUpdateResult[];
  partial_failure: boolean;
  ticket_key: string;
}

/** Update Jira ticket fields. Supports updating Status, Priority, Type, Assignee, Description (markdown), and Sprint assignment. Can update multiple fields in a single call. Handles status transitions automatically and supports assignee lookup by email, display name, or account ID. Requires JIRA_BASE_URL, JIRA_EMAIL, and JIRA_API_TOKEN environment variables (or ATLASSIAN_* as fallback). */
declare function jira_update(input: JiraUpdateInput): Promise<JiraUpdateOutput>;

interface LinearIssueGetInput {
  /** Issue id or identifier (e.g. GUZ-85) */
  id: string;
}

interface LinearIssueGetActivity {
  actor?: string | null;
  summary: string;
  timestamp: string;
}

interface LinearIssueGetComment {
  author?: string | null;
  body: string;
  created_at: string;
  id: string;
  url: string;
}

interface LinearIssueGetOutput {
  activity?: LinearIssueGetActivity[];
  blocked_by?: string[];
  comments?: LinearIssueGetComment[];
  description?: string | null;
  id: string;
  identifier: string;
  parent?: string | null;
  state: string;
  title: string;
  url: string;
}

/** Get one Linear issue by id or identifier (e.g. GUZ-85). Returns id, identifier, title, URL, state, parent, and blocked-by relations. Requires LINEAR_API_KEY environment variable. */
declare function linear_issue_get(input: LinearIssueGetInput): Promise<LinearIssueGetOutput>;

interface LinearIssueListInput {
  /** Fetch all pages (up to 50 items) */
  all?: boolean;
  /** Assignee user UUID or 'me' */
  assignee?: string;
  /** Page cursor for pagination */
  cursor?: string;
  /** Cycle number or id */
  cycle?: string;
  /** Label name */
  label?: string;
  /** Max items per page @default 25 */
  limit?: number;
  /** Project id or name (names need team) */
  project?: string;
  /** Title substring to search */
  query?: string;
  /** Workflow state name (e.g. Todo) */
  state?: string;
  /** Team id, key, or name */
  team?: string;
  /** Only issues updated at or after RFC3339 time (e.g. 2026-01-01T00:00:00Z) */
  updatedAfter?: string;
}

interface LinearIssueListIssueMini {
  blocked_by?: string[];
  description?: string | null;
  id: string;
  identifier: string;
  parent?: string | null;
  state: string;
  title: string;
  url: string;
}

interface LinearIssueListPageInfo {
  endCursor?: string | null;
  hasNextPage: boolean;
}

interface LinearIssueListOutput {
  nodes: LinearIssueListIssueMini[];
  pageInfo: LinearIssueListPageInfo;
}

/** List Linear issues with filters. Returns nodes with id, identifier, title, state, parent, blocked-by plus pageInfo. Requires LINEAR_API_KEY environment variable. */
declare function linear_issue_list(input: LinearIssueListInput): Promise<LinearIssueListOutput>;

interface LinearIssueCreateInput {
  /** Assignee user UUID or 'me' */
  assignee?: string;
  /** Issue description */
  description?: string;
  /** Project id or name (names resolve against team) */
  project?: string;
  /** Workflow state name or UUID */
  state?: string;
  /** Team id, key, or name */
  team: string;
  /** Issue title */
  title: string;
}

interface LinearIssueCreateOutput {
  blocked_by?: string[];
  description?: string | null;
  id: string;
  identifier: string;
  parent?: string | null;
  state: string;
  title: string;
  url: string;
}

/** Create a Linear issue in a team. Returns id, identifier, title, URL, state, parent. Requires LINEAR_API_KEY environment variable. */
declare function linear_issue_create(input: LinearIssueCreateInput): Promise<LinearIssueCreateOutput>;
